/**
 * Definition for a binary tree node.
 * class TreeNode(var _value: Int) {
 *   var value: Int = _value
 *   var left: TreeNode = null
 *   var right: TreeNode = null
 * }
 */
object Solution {
  def isCousins(root: TreeNode, x: Int, y: Int): Boolean = {
    // We will store (parent, depth) for x and y once found
    var xInfo: Option[(TreeNode, Int)] = None
    var yInfo: Option[(TreeNode, Int)] = None

    def dfs(node: TreeNode, parent: TreeNode, depth: Int): Unit = {
      if (node == null) return
      if (node.value == x) xInfo = Some((parent, depth))
      else if (node.value == y) yInfo = Some((parent, depth))
      if (xInfo.isDefined && yInfo.isDefined) return
      dfs(node.left, node, depth + 1)
      dfs(node.right, node, depth + 1)
    }

    dfs(root, null, 0)

    (xInfo, yInfo) match {
      case (Some((xp, xd)), Some((yp, yd))) =>
        xd == yd && xp != yp
      case _ => false
    }
  }
}

